package binding

import (
	"fmt"
)

// sprintfString is a String binding that formats values using fmt.Sprintf
type sprintfString struct {
	base

	format  string
	sources []DataItem
}

// StringToStringWithFormat creates a binding that formats the source string using the provided format.
// The format string should be compatible with fmt.Sprintf and should contain exactly one %s or similar
// string format verb.
//
// Since: 2.2
func StringToStringWithFormat(source String, format string) String {
	if source == nil {
		return NewString() // Return empty binding if source is nil
	}

	ret := &sprintfString{
		format:  format,
		sources: []DataItem{source},
	}
	source.AddListener(ret)
	return ret

package validation

import "fyne.io/fyne/v2"

// NewAllStrings creates a new validator that requires all provided validators to pass.
// The returned validator will only return nil if all the provided validators return nil.
// If any validator fails, the error from the first failing validator is returned.
//
// Since: 2.2
func NewAllStrings(validators ...fyne.StringValidator) fyne.StringValidator {
	return func(s string) error {
		for _, validator := range validators {
			if validator == nil {
				continue
			}
			if err := validator(s); err != nil {
				return err
			}
		}
		return nil
	}
}

package fyne

// Menu stores the information required for a standard menu.
// A menu can pop down from a MainMenu or could be a pop out menu.
type Menu struct {
	Label string
	Items []*MenuItem
}

// NewMenu creates a new menu given the specified label (to show in a MainMenu) and list of items to display.
func NewMenu(label string, items ...*MenuItem) *Menu {
	return &Menu{Label: label, Items: items}
}

// Refresh updates the menu to reflect any changes to its items.
// This will update all windows that are currently displaying this menu.
//
// Since: 2.2
func (m *Menu) Refresh() {
	app := CurrentApp()
	if app == nil {
		return
	}

	for _, window := range app.Driver().AllWindows() {
		if mainMenu := window.MainMenu(); mainMenu != nil {
			// Trigger a refresh of the window to update the menu bar
			if content := window.Content(); content != nil {
				window.Canvas().Refresh(content)
			}
		}
	}
}

// MenuItem is a single item within any menu, it contains a display Label and Action function that is called when tapped.
type MenuItem struct {
	ChildMenu *Menu
	// Since: 2.1
	IsQuit      bool
	IsSeparator bool
	Label       string
	Action      func()
	// Since: 2.1
	Disabled bool
	// Since: 2.1
	Checked bool
	// Icon is an optional icon to display alongside the menu item label.
	//
	// Since: 2.2
	Icon Resource

