// Package desktop provides desktop-specific driver extensions
package desktop

import "fyne.io/fyne/v2"

// App is an extension interface for desktop applications.
// It provides desktop-specific functionality like system tray support.
//
// Since: 2.2
type App interface {
	fyne.App

	// SetSystemTrayMenu sets the system tray menu for the application.
	// This allows the application to add an icon and menu to the system tray.
	// Pass nil to remove the system tray menu.
	SetSystemTrayMenu(menu *fyne.Menu)

	// SetSystemTrayIcon sets the system tray icon for the application.
	// This icon will be displayed in the system tray/notification area.
	// Pass nil to use the default application icon.
	SetSystemTrayIcon(icon fyne.Resource)
}

	if source == nil {
		return NewString() // Return empty binding if source is nil
	}

	// Optimization: if format is "%s", return source directly
	if format == "%s" {
		return source
	}

	return NewSprintf(format, source)
}

// NewSprintf creates a new string binding that formats multiple source data items using fmt.Sprintf.
// The format string follows fmt.Sprintf conventions, and the number of format verbs should match
// the number of source data items provided.
//
// Supported source types: String, Int, Float, Bool, URI
//
// The formatted binding supports reverse parsing via Set() using fmt.Sscanf semantics.
// URI values are parsed via storage.ParseURI.
//
// Since: 2.2
func NewSprintf(format string, sources ...DataItem) String {
	ret := &sprintfString{
		format:  format,
		sources: sources,
	}

	// Add listeners to all sources
	for _, src := range sources {
		if src != nil {
			src.AddListener(ret)
		}
	}

	return ret
}

func (s *sprintfString) Get() (string, error) {
	values := make([]interface{}, len(s.sources))

n, err := fmt.Sscanf(str, s.format, values...)
if err != nil && n == 0 {
	return err
}

// Set the parsed values back to source bindings
for i, src := range s.sources {
	if src == nil || values[i] == nil {
		continue
	}

	switch src := src.(type) {
	case String:
		if strPtr, ok := values[i].(*string); ok {
			if err := src.Set(*strPtr); err != nil {
				return err
			}
		}
	case Int:
		if intPtr, ok := values[i].(*int); ok {
			if err := src.Set(*intPtr); err != nil {
				return err
			}
		}
	case Float:
		if floatPtr, ok := values[i].(*float64); ok {
			if err := src.Set(*floatPtr); err != nil {
				return err
			}
		}
	case Bool:
		if boolPtr, ok := values[i].(*bool); ok {
			if err := src.Set(*boolPtr); err != nil {
				return err
			}
		}
	case URI:
		if strPtr, ok := values[i].(*string); ok {
			uri, err := storage.ParseURI(*strPtr)
			if err != nil {
				return err
			}
			if err := src.Set(uri); err != nil {
				return err
			}
		}
	}
}

return nil

charMin := r.entry.placeholderProvider().charMinSize(r.entry.Password, r.entry.TextStyle)
minSize := charMin.Add(fyne.NewSize(theme.Padding()*2, theme.Padding()*2))

if r.entry.MultiLine {
	// ensure multiline height is at least charMinSize * multilineRows
	// Use MinRowsVisible if set, otherwise use default
	rows := multiLineRows
	if r.entry.MinRowsVisible > 0 {
		rows = r.entry.MinRowsVisible
	}
	rowHeight := charMin.Height * float32(rows)
	minSize.Height = fyne.Max(minSize.Height, rowHeight+float32(rows-1)*theme.Padding())
}

return minSize.Add(fyne.NewSize(theme.Padding()*4, theme.Padding()*2))

