	values := make([]interface{}, len(s.sources))

	for i, src := range s.sources {
		if src == nil {
			values[i] = nil
			continue
		}

		switch src := src.(type) {
		case String:
			if val, err := src.Get(); err == nil {
				values[i] = val
			} else {
				values[i] = ""
			}
		case Int:
			if val, err := src.Get(); err == nil {
				values[i] = val
			} else {
				values[i] = 0
			}
		case Float:
			if val, err := src.Get(); err == nil {
				values[i] = val
			} else {
				values[i] = 0.0
			}
		case Bool:
			if val, err := src.Get(); err == nil {
				values[i] = val
			} else {
				values[i] = false
			}
		case URI:
			if val, err := src.Get(); err == nil {
				if val != nil {
					values[i] = val.String()
				} else {
					values[i] = ""
				}
			} else {
				values[i] = ""
			}
