}

func (s *sprintfString) Set(str string) error {
	if len(s.sources) == 0 {
		return nil
	}

	// Create pointers to receive parsed values
	values := make([]interface{}, len(s.sources))

	for i, src := range s.sources {
		if src == nil {
			continue
		}

		switch src.(type) {
		case String:
			var val string
			values[i] = &val
		case Int:
			var val int
			values[i] = &val
		case Float:
			var val float64
			values[i] = &val
		case Bool:
			var val bool
			values[i] = &val
		case URI:
			var val string
			values[i] = &val
		default:
			return fmt.Errorf("unsupported binding type for parsing")
		}
	}

